/**
 * Prints a square pattern of stars with n rows and n columns.
 * @param {number} n - The size of the square (number of rows and columns).
 * Example: For n = 5, the output will be:
    * * * * *
    * * * * *
    * * * * *
    * * * * *
    * * * * *
 */
function printStarSquare(n) {
    for (let i = 0; i < n; i++) {
        let row = "";
        for (let j = 0; j < n; j++) {
            row += "* ";
        }
        console.log(row);
    }
}

printStarSquare(5);
